  "Time to lift the heavy thing again.": "আবার ভারী জিনিসটা তোলার সময়।",
  "Last set. Then you can sit down forever.": "শেষ সেট। তারপর চিরকাল বসে থাকতে পারবেন।",
  "Final set. Try to look like you meant it.": "শেষ সেট। এমন ভাব করুন যেন ইচ্ছে করেই।",
  "New record. I’ll alert absolutely nobody.": "নতুন রেকর্ড। আমি একদম কাউকে জানাব না।",
  "Personal best. The weights have filed a complaint.": "ব্যক্তিগত সেরা। ওজনগুলো নালিশ করেছে।",
