  "Rounds over your stations. Tap Done, move on, repeat.": "আপনার স্টেশনগুলোতে রাউন্ড। হয়েছে চাপুন, এগোন, আবার।",
  "As many rounds as you can before the clock says stop.": "ঘড়ি থামতে বলার আগে যত রাউন্ড পারেন।",
  "A new interval every minute on the minute. Finish early, rest the rest.": "প্রতি মিনিটের শুরুতে নতুন ইন্টারভাল। আগে শেষ হলে বাকিটা বিশ্রাম।",
  "Work, rest, repeat. Tabata is 20 on, 10 off, 8 times.": "কাজ, বিশ্রাম, আবার। টাবাটা মানে 20 কাজ, 10 বিশ্রাম, 8 বার।",
  "Run a bit, walk a bit, run a little more each level. Three finished runs move you up.": "একটু দৌড়, একটু হাঁটা, প্রতি লেভেলে একটু বেশি দৌড়। তিনটি সম্পূর্ণ দৌড়ে লেভেল বাড়ে।",
  "Same muscle and exercise type. The movement may differ.": "একই পেশি ও ব্যায়ামের ধরন। নড়াচড়া ভিন্ন হতে পারে।",
  "Related muscles and exercise type. The movement may differ.": "সম্পর্কিত পেশি ও একই ব্যায়ামের ধরন। নড়াচড়া ভিন্ন হতে পারে।",
  "Same muscle, different exercise type. Check suitability.": "একই পেশি, ভিন্ন ব্যায়ামের ধরন। উপযুক্ত কি না চেক করুন।",
