  'Set · sign in as “{0}”': 'সেট করা · “{0}” হিসেবে সাইন ইন',
  'Not set. Handy for signing in where passkeys don’t work.': 'সেট করা নেই। যেখানে পাসকি কাজ করে না, সেখানে সাইন ইন করতে কাজে লাগে।',
  'Set a password': 'পাসওয়ার্ড সেট করুন',
  'Change password': 'পাসওয়ার্ড বদলান',
  'Sign in as “{0}” with it on devices where passkeys do not work. Saving signs you out everywhere else, and paired phones have to be paired again.': 'যেসব ডিভাইসে পাসকি কাজ করে না, সেখানে এটি দিয়ে “{0}” হিসেবে সাইন ইন করুন। সেভ করলে অন্য সব জায়গা থেকে সাইন আউট হবেন, আর পেয়ার করা ফোনগুলো আবার পেয়ার করতে হবে।',
  'Confirm with passkey & save': 'পাসকি দিয়ে নিশ্চিত করে সেভ করুন',
