  'Not set. Lets you sign in with an e-mail instead of your name.': 'সেট করা নেই। নামের বদলে ই-মেইল দিয়ে সাইন ইন করতে দেয়।',
  'Change sign-in e-mail': 'সাইন-ইন ই-মেইল বদলান',
  'Add a sign-in e-mail': 'সাইন-ইন ই-মেইল যোগ করুন',
  'Type it at “Sign in with password” instead of your profile name. We never send anything to it; a forgotten password is still reset by your admin.': '“পাসওয়ার্ড দিয়ে সাইন ইন করুন”-এ প্রোফাইলের নামের বদলে এটি লিখুন। আমরা এতে কখনো কিছু পাঠাই না; পাসওয়ার্ড ভুলে গেলে এখনও আপনার অ্যাডমিনই রিসেট করবেন।',
  'E-mail address': 'ই-মেইল ঠিকানা',
