  'E-mail removed': 'ই-মেইল সরানো হয়েছে',
  'Too many attempts. Try again {0}.': 'অনেকবার চেষ্টা করা হয়েছে। {0} আবার চেষ্টা করুন।',
  'Use at least {0} characters.': 'অন্তত {0}টি অক্ষর ব্যবহার করুন।',
  'That password is too long.': 'পাসওয়ার্ডটি খুব লম্বা।',
  'That password is too easy to guess. Try a longer one, or a few random words strung together.': 'পাসওয়ার্ডটি সহজেই অনুমান করা যায়। আরও লম্বা একটি, বা কয়েকটি এলোমেলো শব্দ মিলিয়ে চেষ্টা করুন।',
  'Another profile already signs in with this name.': 'অন্য একটি প্রোফাইল ইতিমধ্যে এই নামে সাইন ইন করে।',
  'That invite code is not valid.': 'ইনভাইট কোডটি বৈধ নয়।',
  'Your current password is not right.': 'আপনার বর্তমান পাসওয়ার্ড সঠিক নয়।',
  'Your passkey could not be confirmed.': 'আপনার পাসকি নিশ্চিত করা যায়নি।',
  'This password is the only way into your profile, so it cannot be removed.': 'এই পাসওয়ার্ডই আপনার প্রোফাইলে ঢোকার একমাত্র উপায়, তাই এটি সরানো যাবে না।',
  'That reset code is wrong or has expired. Ask your admin for a new one.': 'রিসেট কোডটি ভুল বা মেয়াদোত্তীর্ণ। অ্যাডমিনের কাছে নতুন একটি চান।',
  'This account has been disabled.': 'এই অ্যাকাউন্ট নিষ্ক্রিয় করা হয়েছে।',
