  'Deletes your plan, workouts, body weight, photos and videos from your profile on this server and on every signed-in device. This cannot be undone.': 'এই সার্ভারে আপনার প্রোফাইল থেকে এবং সাইন ইন করা প্রতিটি ডিভাইস থেকে আপনার প্ল্যান, ওয়ার্কআউট, শরীরের ওজন, ছবি ও ভিডিও মুছে দেয়। এটি আর ফেরানো যাবে না।',
