  'A deload routine opens at the numbers set here, so the progression above does not apply to it.': 'ডিলোড রুটিন এখানে সেট করা সংখ্যা দিয়ে শুরু হয়, তাই উপরের প্রগ্রেশন এতে প্রযোজ্য নয়।',
