  'Targets stay where you set them.': 'লক্ষ্যগুলো যেখানে সেট করেছেন সেখানেই থাকে।',
  'Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.': 'প্রতিটি সেটের প্রতিটি রেপ হলে ওজন বাড়ে। বারবার না হলে ডিলোড হয়।',
  'Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.': 'দুটি সাধারণ সেট আর একটি শেষ সেট ফেইলিউর পর্যন্ত। ওই সেটে লক্ষ্য ছাড়ালে ওজন বাড়ে (রেপ দ্বিগুণ করলে দ্বিগুণ)। একবার ব্যর্থ হলে ১০ % কমে যায়।',
  'Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.': 'একই ওজনে একটি রেপ রেঞ্জ ধরে উপরে উঠুন। প্রতিটি সেটে রেঞ্জের শীর্ষে পৌঁছালে ওজন বাড়ে, রেপ আবার নিচে ফেরে।',
  'Hold every set for the full duration and the target goes up.': 'প্রতিটি সেট পুরো সময় ধরে রাখলে লক্ষ্য বাড়ে।',
  'Nothing logged yet, so this session sets the baseline.': 'এখনও কিছু লগ করা হয়নি, তাই এই সেশন ভিত্তি ঠিক করবে।',
  'Held every set for the full time. Target goes up by {0}s.': 'প্রতিটি সেট পুরো সময় ধরে রেখেছেন। লক্ষ্য {0} সে. বাড়ল।',
  'Short {0} sessions in a row. Back off to {1}s and build up again.': 'পরপর {0}টি সেশনে কম হয়েছে। {1} সে.-এ নেমে আবার বাড়ান।',
  'Came up short last time. Same target again.': 'গতবার কম হয়েছিল। আবার একই লক্ষ্য।',
  'Top of the rep range in every set. {0} {1} more, back to {2} reps.': 'প্রতিটি সেটে রেপ রেঞ্জের শীর্ষে। আরও {0} {1}, আবার {2} রেপে।',
  'Stuck for {0} sessions. Deload to {1} {2}.': '{0}টি সেশন আটকে আছেন। {1} {2}-এ ডিলোড করুন।',
  'Same weight, aim for {0} reps this time.': 'একই ওজন, এবার {0} রেপের লক্ষ্য রাখুন।',
  'Last set hit {0} reps, twice the target! Take a double jump of {1} {2}.': 'শেষ সেটে {0} রেপ হয়েছে, লক্ষ্যের দ্বিগুণ! {1} {2}-এর দ্বিগুণ লাফ দিন।',
  'Every rep last time. {0} {1} more.': 'গতবার সব রেপ হয়েছে। আরও {0} {1}।',
  'Every rep last time. {0} {1} less help.': 'গতবার সব রেপ হয়েছে। {0} {1} কম সহায়তা।',
  'Top of the rep range in every set. {0} {1} less help, back to {2} reps.': 'প্রতিটি সেটে রেপ রেঞ্জের শীর্ষে। {0} {1} কম সহায়তা, আবার {2} রেপে।',
  'Missed reps. {0} {1} of help while you build back up.': 'রেপ বাদ গেছে। আবার গড়ে তোলার সময় {0} {1} সহায়তা।',
  'Stuck for {0} sessions. Back to {1} {2} of help, then build up again.': '{0}টি সেশন আটকে আছেন। আবার {1} {2} সহায়তায় ফিরুন, তারপর আবার গড়ে তুলুন।',
  'Missed reps {0} sessions running. Reset to {1} {2} and work back up.': 'পরপর {0}টি সেশনে রেপ বাদ গেছে। {1} {2}-এ রিসেট করে আবার উঠুন।',
  'Missed reps. Reset to {0} {1} and work back up.': 'রেপ বাদ গেছে। {0} {1}-এ রিসেট করে আবার উঠুন।',
  'Missed reps last time. Same weight again ({0} of {1} to go).': 'গতবার রেপ বাদ গেছে। আবার একই ওজন ({1}-এর মধ্যে আর {0} বাকি)।',
  'Bodyweight: every rep last time, so go for {0} this time.': 'শরীরের ওজন: গতবার সব রেপ হয়েছে, তাই এবার {0} চেষ্টা করুন।',
  'Bodyweight: same target again until every set is clean.': 'শরীরের ওজন: প্রতিটি সেট নিখুঁত না হওয়া পর্যন্ত একই লক্ষ্য।',
