  'Tap how many reps you had left, or type an exact {0}.': 'কতগুলো রেপ বাকি ছিল তাতে ট্যাপ করুন, অথবা সঠিক {0} লিখুন।',
  'Exact {0}': 'সঠিক {0}',
  'Clear rating': 'রেটিং মুছুন',
  'RIR counts the reps you left in the tank; RPE reads the same effort off a 10-point scale, so RPE ≈ 10 − RIR. Pick whichever you already think in.': 'RIR গোনে কতগুলো রেপ বাকি রেখেছেন; RPE একই পরিশ্রম ১০-পয়েন্ট স্কেলে মাপে, তাই RPE ≈ ১০ − RIR। যেটিতে আপনি অভ্যস্ত, সেটি বেছে নিন।',
  'The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.': 'হাইলাইট করা সারিতেই বেশিরভাগ ওয়ার্কিং সেট পড়ে। ইতিমধ্যে লগ করা সেটগুলো নিজেদের স্কেল রাখে, আর অন্য কিছুই এই মান পড়ে না, তাই প্রগ্রেশন ও আনুমানিক 1RM প্রভাবিত হয় না।',
