  'Most working sets belong close to failure, not at it. Half at the floor and half at the top still average out to a healthy-looking middle.': 'বেশিরভাগ ওয়ার্কিং সেট ফেইলিউরের কাছাকাছি হওয়া উচিত, ঠিক ফেইলিউরে নয়। অর্ধেক নিচে আর অর্ধেক শীর্ষে থাকলেও গড়টা দেখতে স্বাস্থ্যকর মাঝামাঝি লাগে।',
