  'No weight to enter. Just log the reps.': 'কোনো ওজন লেখার দরকার নেই। শুধু রেপ লগ করুন।',
  'Ask for a weight on every set.': 'প্রতিটি সেটে ওজন জিজ্ঞেস করুন।',
  'For dips or pull-ups with a belt. Progression then follows the weight.': 'বেল্ট দিয়ে ডিপস বা পুল-আপের জন্য। তখন প্রগ্রেশন ওজন ফলো করে।',
  'For lunges, single-arm rows and the like.': 'লাঞ্জ, এক হাতের রো ইত্যাদির জন্য।',
  'Top of the range': 'রেঞ্জের শীর্ষ',
  'Reps climb by one whenever every set was clean. Set a ceiling to add sets instead of reps forever.': 'প্রতিটি সেট নিখুঁত হলে রেপ একটি করে বাড়ে। চিরকাল রেপ না বাড়িয়ে সেট যোগ করতে একটি সীমা সেট করুন।',
  'Reps climb to {0}, then a set is added and the reps start over. At {1} sets it asks you to add weight instead.': 'রেপ {0} পর্যন্ত বাড়ে, তারপর একটি সেট যোগ হয় এবং রেপ আবার শুরু হয়। {1} সেটে পৌঁছালে বদলে ওজন বাড়াতে বলে।',
  'Added ({0})': 'যোগ করা ({0})',
