  'Your name, your sign-in details and everything else about your account stay here. Other people’s data is never included.': 'আপনার নাম, সাইন-ইন তথ্য এবং আপনার অ্যাকাউন্টের বাকি সবকিছু এখানেই থাকে। অন্য কারও ডেটা কখনো যুক্ত হয় না।',
  'The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.': 'কোচ ডাক্তার বা ফিজিওথেরাপিস্ট নয়। কোথাও ব্যথা হলে একজন পেশাদারের পরামর্শ নিন।',
