  'On this phone the Coach can only look while the app is open: right after a workout, or the next time you open it.': 'এই ফোনে কোচ শুধু অ্যাপ খোলা থাকলেই দেখতে পারে: ওয়ার্কআউটের ঠিক পরে, অথবা পরের বার অ্যাপ খুললে।',
