  'Pick everything you have access to. Leave it empty and the Coach will use the whole library.': 'যা যা আপনার কাছে আছে সব বেছে নিন। খালি রাখলে কোচ পুরো লাইব্রেরি ব্যবহার করবে।',
  'Anything to work around?': 'কিছু এড়িয়ে চলার আছে?',
  'Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.': 'চোট, সমস্যা করা জয়েন্ট, যে নড়াচড়া আপনি করতে পারেন না, অথবা ফ্ল্যাটে ভোর ৬টায় ট্রেনিংয়ের মতো বাস্তব সীমাবদ্ধতা।',
  'e.g. “dodgy left shoulder, no barbell overhead press”': 'যেমন “বাঁ কাঁধে সমস্যা, বারবেল ওভারহেড প্রেস নয়”',
  'If something actually hurts, see a professional. The Coach will program conservatively, but it can’t diagnose anything.': 'সত্যিই কোথাও ব্যথা হলে একজন পেশাদার দেখান। কোচ সাবধানে প্রোগ্রাম করবে, কিন্তু কিছু নির্ণয় করতে পারে না।',
