  'Body-weight exercises are always available, unless they need a pull-up bar or a bench.': 'শরীরের ওজনের ব্যায়াম সবসময় পাওয়া যায়, যদি না সেগুলোর জন্য পুল-আপ বার বা বেঞ্চ লাগে।',
  '{0} of {1} exercises need equipment outside "{2}"': '{1}টির মধ্যে {0}টি ব্যায়ামে "{2}"-এর বাইরের ইকুইপমেন্ট লাগে',
  'Needs {0}, which isn’t in your active profile': '{0} লাগে, যা আপনার সক্রিয় প্রোফাইলে নেই',
  'Filter by equipment': 'ইকুইপমেন্ট অনুযায়ী ফিল্টার করুন',
  'Active profile': 'সক্রিয় প্রোফাইল',
  '{0} equipment types': '{0} ধরনের ইকুইপমেন্ট',
  'Add equipment profile': 'ইকুইপমেন্ট প্রোফাইল যোগ করুন',
  'Delete profile?': 'প্রোফাইল মুছবেন?',
  '"{0}" and its equipment list will be removed.': '"{0}" এবং এর ইকুইপমেন্টের তালিকা সরানো হবে।',
  'Filters the exercise library and picker, and flags routine exercises that need something you don’t have in the active profile.': 'ব্যায়াম লাইব্রেরি ও বাছাইয়ের তালিকা ফিল্টার করে, এবং সক্রিয় প্রোফাইলে নেই এমন কিছু লাগে এমন রুটিনের ব্যায়ামগুলো চিহ্নিত করে।',
