  'Disconnect from your server?': 'আপনার সার্ভার থেকে সংযোগ বিচ্ছিন্ন করবেন?',
  'Disconnected. Back to local-only': 'সংযোগ বিচ্ছিন্ন। আবার শুধু লোকাল',
  'Connect to my server': 'আমার সার্ভারে সংযোগ করুন',
  'Sync this device to your own self-hosted openGym instead.': 'বদলে এই ডিভাইসটি আপনার নিজের সেলফ-হোস্টেড openGym-এর সাথে সিঙ্ক করুন।',
  'Pair the mobile app': 'মোবাইল অ্যাপ পেয়ার করুন',
  'Connect the openGym app on your phone to this account.': 'আপনার ফোনের openGym অ্যাপটি এই অ্যাকাউন্টের সাথে সংযুক্ত করুন।',
  'On the openGym app, choose “Connect to my server”, then enter this address and the code below. It expires in 5 minutes.': 'openGym অ্যাপে “আমার সার্ভারে সংযোগ করুন” বেছে নিন, তারপর এই ঠিকানা এবং নিচের কোডটি লিখুন। এর মেয়াদ ৫ মিনিট।',
  'Enter your server address and the code': 'আপনার সার্ভারের ঠিকানা ও কোড লিখুন',
