  '{0} workouts and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': 'সাইন আউট থাকা অবস্থায় এই ডিভাইসে {0}টি ওয়ার্কআউট ও {1}টি ওজন মাপা লগ হয়েছে। সেগুলো আপনার প্রোফাইলে যোগ করুন, অথবা প্রোফাইলটি সার্ভারে যেমন আছে ঠিক তেমন রাখুন।',
