  'Server error (HTTP {0})': 'সার্ভার ত্রুটি (HTTP {0})',
  'Your server answered with an error (HTTP {0}). Your changes are kept here.': 'আপনার সার্ভার একটি ত্রুটি দিয়ে উত্তর দিয়েছে (HTTP {0})। আপনার পরিবর্তনগুলো এখানে রাখা আছে।',
