  'This phone is no longer paired with your server. Your changes are kept here.': 'এই ফোন আর আপনার সার্ভারের সাথে পেয়ার করা নেই। আপনার পরিবর্তনগুলো এখানে রাখা আছে।',
  'The server refuses this phone': 'সার্ভার এই ফোন প্রত্যাখ্যান করছে',
  'Your server no longer accepts this phone. Your changes are kept here.': 'আপনার সার্ভার আর এই ফোন গ্রহণ করে না। আপনার পরিবর্তনগুলো এখানে রাখা আছে।',
  'On this phone only, not connected to a server': 'শুধু এই ফোনে, কোনো সার্ভারের সাথে সংযুক্ত নয়',
