  'Sign out anyway': 'তবুও সাইন আউট করুন',
  'Couldn’t keep a copy of the changes on this device. Nothing was removed.': 'এই ডিভাইসে পরিবর্তনগুলোর কপি রাখা যায়নি। কিছুই সরানো হয়নি।',
  'Not everything is on your server yet': 'সবকিছু এখনও আপনার সার্ভারে পৌঁছায়নি',
  'Not on your server yet: {0}': 'এখনও আপনার সার্ভারে নেই: {0}',
  'Some changes on this device have not reached your server.': 'এই ডিভাইসের কিছু পরিবর্তন আপনার সার্ভারে পৌঁছায়নি।',
  'Try again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'আবার চেষ্টা করুন, অথবা আগে একটি ব্যাকআপ এক্সপোর্ট করুন। তবুও এগিয়ে গেলে, এই ডিভাইস আবার এই অ্যাকাউন্ট হিসেবে এই সার্ভারে সংযুক্ত না হওয়া পর্যন্ত এই পরিবর্তনগুলোর একটি কপি এখানে থাকবে। তখন সেগুলো আবার যোগ হবে।',
  'Syncing…': 'সিঙ্ক হচ্ছে…',
  'Try again': 'আবার চেষ্টা করুন',
  'Last synced: {0}': 'শেষ সিঙ্ক: {0}',
  'Not synced with this server yet': 'এখনও এই সার্ভারের সাথে সিঙ্ক হয়নি',
  'Server & sync': 'সার্ভার ও সিঙ্ক',
  'Signed in as {0}': '{0} হিসেবে সাইন ইন করা',
  'Sync now': 'এখনই সিঙ্ক করুন',
  'Your changes are kept here, and merged into your account once it is paired again.': 'আপনার পরিবর্তনগুলো এখানে রাখা আছে, এবং আবার পেয়ার হলে আপনার অ্যাকাউন্টে মিলিয়ে দেওয়া হবে।',
  'Your changes are kept here, and merged into your account once you are signed in again.': 'আপনার পরিবর্তনগুলো এখানে রাখা আছে, এবং আবার সাইন ইন করলে আপনার অ্যাকাউন্টে মিলিয়ে দেওয়া হবে।',
  'Changes kept for {0}': '{0}-এর জন্য পরিবর্তন রাখা আছে',
  'Added back when this device connects as that account again.': 'এই ডিভাইস আবার ওই অ্যাকাউন্ট হিসেবে সংযুক্ত হলে আবার যোগ হবে।',
  'The changes your server has not seen are kept on this device, and added back when it connects as this account again.': 'যে পরিবর্তনগুলো আপনার সার্ভার দেখেনি সেগুলো এই ডিভাইসে রাখা থাকে, এবং আবার এই অ্যাকাউন্ট হিসেবে সংযুক্ত হলে যোগ হয়।',
  'This phone switches back to local-only and its copy of your account is removed. First it checks that your server has every change. If not, you choose what happens to them.': 'এই ফোন আবার শুধু লোকাল মোডে ফেরে এবং আপনার অ্যাকাউন্টের কপি সরিয়ে দেওয়া হয়। আগে দেখা হয় আপনার সার্ভারে সব পরিবর্তন আছে কি না। না থাকলে, সেগুলোর কী হবে আপনি বেছে নেবেন।',
  'Your data is removed from this browser; your profile on the server keeps it. First it checks that the server has every change. If not, you choose what happens to them.': 'আপনার ডেটা এই ব্রাউজার থেকে সরানো হয়; সার্ভারে আপনার প্রোফাইলে তা থাকে। আগে দেখা হয় সার্ভারে সব পরিবর্তন আছে কি না। না থাকলে, সেগুলোর কী হবে আপনি বেছে নেবেন।',
  'Signs this profile out on every device, including this one. Phones paired with it are disconnected and have to be paired again. Your passkeys keep working, so you can sign in with them again anytime.': 'এটি সহ প্রতিটি ডিভাইসে এই প্রোফাইল সাইন আউট করে। এর সাথে পেয়ার করা ফোনগুলোর সংযোগ বিচ্ছিন্ন হয় এবং আবার পেয়ার করতে হয়। আপনার পাসকি কাজ করতে থাকে, তাই যেকোনো সময় আবার সেগুলো দিয়ে সাইন ইন করতে পারবেন।',
