  // --- demo build (v1.3.7) ---
  'A pull for every press, so the shoulders stay balanced.': 'প্রতিটি প্রেসের জন্য একটি পুল, যাতে কাঁধের ভারসাম্য থাকে।',
  'A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.': 'সপ্তাহে তিনটি সেশনে দুই দিনের পালাক্রম, আপনার তালিকার ইকুইপমেন্ট ঘিরে তৈরি। আগে কম্পাউন্ড, প্রতিটি প্রেসের জন্য একটি পুল, এবং দিনগুলোর মধ্যে যথেষ্ট মিল, যাতে কোনো কিছুই দুই সপ্তাহ ট্রেনিং ছাড়া না থাকে।',
  'Based on the training already in this demo profile.': 'এই ডেমো প্রোফাইলে ইতিমধ্যে থাকা ট্রেনিংয়ের ভিত্তিতে।',
  'Body weight has been flat for four weeks while the goal is to gain. That’s a kitchen problem, not a training one. The plan isn’t what’s holding it back.': 'লক্ষ্য ওজন বাড়ানো হলেও চার সপ্তাহ ধরে শরীরের ওজন একই আছে। এটি ট্রেনিংয়ের নয়, রান্নাঘরের সমস্যা। প্ল্যান এটিকে আটকে রাখছে না।',
  'Demo': 'ডেমো',
  'Demo data reset': 'ডেমো ডেটা রিসেট হয়েছে',
  'Direct arm work, since you asked for it.': 'সরাসরি বাহুর কাজ, যেহেতু আপনি চেয়েছিলেন।',
  'Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.': 'এই ব্যায়ামের প্রতিটি সেরা সেট টানা তিনটি সেশনে RPE ৯.৫ বা তার বেশি ছিল, আর ওজন নড়েনি। চার সপ্তাহের জন্য নড়াচড়াটি বদলালে সাধারণত একই ব্যায়াম ঘষে যাওয়ার চেয়ে দ্রুত এই আটকে থাকা কাটে।',
  'Example data, stored only in this browser. Go wild and change anything you like.': 'উদাহরণ ডেটা, শুধু এই ব্রাউজারে রাখা। ইচ্ছেমতো যা খুশি বদলান।',
  'Full body A': 'ফুল বডি A',
  'Full body B': 'ফুল বডি B',
  'Horizontal pressing, the other half of the session.': 'অনুভূমিক প্রেসিং, সেশনের বাকি অর্ধেক।',
  'Live demo. Everything stays in this browser.': 'লাইভ ডেমো। সবকিছু এই ব্রাউজারেই থাকে।',
  'No training history yet, so starting conservatively.': 'এখনও কোনো ট্রেনিং ইতিহাস নেই, তাই সাবধানে শুরু করা হচ্ছে।',
  'Passkey sign-in, sync across your devices, your own data.': 'পাসকি দিয়ে সাইন ইন, আপনার ডিভাইসগুলোতে সিঙ্ক, আপনার নিজের ডেটা।',
  'Puts the example plan, workouts and weigh-ins back the way they started.': 'উদাহরণের প্ল্যান, ওয়ার্কআউট ও ওজন মাপা শুরুতে যেমন ছিল তেমন ফিরিয়ে দেয়।',
  'Reset': 'রিসেট',
  'Reset demo data': 'ডেমো ডেটা রিসেট করুন',
  'Reset demo data?': 'ডেমো ডেটা রিসেট করবেন?',
  'Revised as you asked. Everything you did not question is exactly as it was.': 'আপনার কথামতো সংশোধন করা হয়েছে। যেসব নিয়ে আপনি প্রশ্ন তোলেননি সেগুলো ঠিক আগের মতোই আছে।',
  'Same pattern, higher reps than day A.': 'একই প্যাটার্ন, দিন A-এর চেয়ে বেশি রেপ।',
  'Self-host it in a minute →': 'এক মিনিটে নিজে হোস্ট করুন →',
  'Self-host openGym': 'openGym নিজে হোস্ট করুন',
  'Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.': 'সেশনগুলো প্রায় পনেরো মিনিট বেশি চলছে। একটি সেট কম হলে এই সহায়ক ব্যায়ামেরই সবচেয়ে কম ক্ষতি।',
  'Start the demo': 'ডেমো শুরু করুন',
  'The main lower-body driver, where most of the strength comes from.': 'শরীরের নিচের অংশের প্রধান চালিকা, বেশিরভাগ শক্তি এখান থেকেই আসে।',
  'The same patterns, different variations: enough overlap to progress, enough difference to stay fresh.': 'একই প্যাটার্ন, ভিন্ন ভ্যারিয়েশন: প্রগ্রেসের জন্য যথেষ্ট মিল, সতেজ থাকার জন্য যথেষ্ট ভিন্নতা।',
  'The two big lower-body and pressing patterns first, while you are fresh.': 'শরীরের নিচের অংশ ও প্রেসিংয়ের দুটি বড় প্যাটার্ন আগে, যখন আপনি সতেজ থাকেন।',
  'This demo runs entirely in your browser on example data. Nothing is sent anywhere. Passkey sign-in and sync across your devices come with the openGym server, which you get by self-hosting it.': 'এই ডেমো পুরোপুরি আপনার ব্রাউজারে উদাহরণ ডেটা দিয়ে চলে। কিছুই কোথাও পাঠানো হয় না। পাসকি দিয়ে সাইন ইন ও আপনার ডিভাইসগুলোতে সিঙ্ক openGym সার্ভারের সাথে আসে, যা আপনি নিজে হোস্ট করে পান।',
  'Three things worth changing, and one worth knowing about. Everything else is working: the squat and the pulls are both progressing on schedule.': 'তিনটি জিনিস বদলানোর মতো, আর একটি জেনে রাখার মতো। বাকি সব ঠিকঠাক চলছে: স্কোয়াট ও পুল দুটোই সময়মতো এগোচ্ছে।',
  'Vertical pressing.': 'উল্লম্ব প্রেসিং।',
  'You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.': 'টানা তিন সপ্তাহ আপনি এই সেশন শনিবারে সরিয়েছেন। বারবার বদলানোর চেয়ে প্ল্যানেই সেটি থাকা ভালো।',
