  'See which lift is holding back the rest.': 'দেখুন কোন লিফট বাকিগুলোকে পিছিয়ে রাখছে।',
  'Compare your lifts against a published ratio table to find the weak link.': 'দুর্বল জায়গা খুঁজতে আপনার লিফটগুলোকে একটি প্রকাশিত অনুপাতের তালিকার সাথে তুলনা করুন।',
