  'Custom': 'কাস্টম',
  'Log your body weight to score this lift.': 'এই লিফটের স্কোর পেতে আপনার শরীরের ওজন লগ করুন।',
  'Log the anchor lift to score this one.': 'এটির স্কোর পেতে ভিত্তি লিফটটি লগ করুন।',
  'Not scored': 'স্কোর করা হয়নি',
  'The server cannot be reached': 'সার্ভারে পৌঁছানো যাচ্ছে না',
  'Your server can’t be reached. Your changes are saved on this device and sync once it answers again.': 'আপনার সার্ভারে পৌঁছানো যাচ্ছে না। আপনার পরিবর্তনগুলো এই ডিভাইসে সেভ আছে এবং সার্ভার আবার সাড়া দিলে সিঙ্ক হবে।',
  'Your server can’t be reached. Showing the last copy synced with it.': 'আপনার সার্ভারে পৌঁছানো যাচ্ছে না। এর সাথে সর্বশেষ সিঙ্ক হওয়া কপি দেখানো হচ্ছে।',
  'Server address unknown': 'সার্ভারের ঠিকানা অজানা',
  'Pair again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'আবার পেয়ার করুন, অথবা আগে একটি ব্যাকআপ এক্সপোর্ট করুন। তবুও এগিয়ে গেলে, এই ডিভাইস আবার এই অ্যাকাউন্ট হিসেবে এই সার্ভারে সংযুক্ত না হওয়া পর্যন্ত এই পরিবর্তনগুলোর একটি কপি এখানে থাকবে। তখন সেগুলো আবার যোগ হবে।',
  'Sign in again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'আবার সাইন ইন করুন, অথবা আগে একটি ব্যাকআপ এক্সপোর্ট করুন। তবুও এগিয়ে গেলে, এই ডিভাইস আবার এই অ্যাকাউন্ট হিসেবে এই সার্ভারে সংযুক্ত না হওয়া পর্যন্ত এই পরিবর্তনগুলোর একটি কপি এখানে থাকবে। তখন সেগুলো আবার যোগ হবে।',
