  'Every exercise in this workout': 'এই ওয়ার্কআউটের প্রতিটি ব্যায়াম',
  'No sets are left in this workout, so there is nothing to save. Delete it from your history?': 'এই ওয়ার্কআউটে আর কোনো সেট নেই, তাই সেভ করার কিছু নেই। আপনার ইতিহাস থেকে মুছে ফেলবেন?',
