  'This browser cannot read that file.': 'এই ব্রাউজার ফাইলটি পড়তে পারে না।',
  'There is no room left on this device for that file.': 'এই ফাইলের জন্য এই ডিভাইসে আর জায়গা নেই।',
  'This video may not play on every device. MP4 (H.264) plays everywhere.': 'এই ভিডিও সব ডিভাইসে না-ও চলতে পারে। MP4 (H.264) সব জায়গায় চলে।',
  'Your photo and video space on the server is full ({0} of {1} MB).': 'সার্ভারে আপনার ছবি ও ভিডিওর জায়গা পূর্ণ ({1} MB-এর মধ্যে {0})।',
  'The server refused the file as too large.': 'ফাইলটি খুব বড় বলে সার্ভার প্রত্যাখ্যান করেছে।',
  'Kept on this device only. Export with photos & videos keeps a copy.': 'শুধু এই ডিভাইসে রাখা। “ছবি ও ভিডিওসহ এক্সপোর্ট” একটি কপি রাখে।',
  'Your server does not store photos and videos yet.': 'আপনার সার্ভার এখনও ছবি ও ভিডিও রাখে না।',
  'This browser cannot store photos or videos here.': 'এই ব্রাউজার এখানে ছবি বা ভিডিও রাখতে পারে না।',
