  'Its photo or video moves to the new workout.': 'এর ছবি বা ভিডিও নতুন ওয়ার্কআউটে চলে যাবে।',
  'Its {0} photos or videos move to the new workout.': 'এর {0}টি ছবি বা ভিডিও নতুন ওয়ার্কআউটে চলে যাবে।',
  'The server has 1 workout that is not in this backup, logged since it was made or on another device. Replacing deletes it.': 'সার্ভারে ১টি ওয়ার্কআউট আছে যা এই ব্যাকআপে নেই — এটি তৈরির পরে বা অন্য ডিভাইসে লগ হয়েছে। রিপ্লেস করলে সেটি মুছে যাবে।',
  'The server has {0} workouts that are not in this backup, logged since it was made or on another device. Replacing deletes them.': 'সার্ভারে {0}টি ওয়ার্কআউট আছে যা এই ব্যাকআপে নেই — এটি তৈরির পরে বা অন্য ডিভাইসে লগ হয়েছে। রিপ্লেস করলে সেগুলো মুছে যাবে।',
