  'Nothing syncs until you say whether this device’s workouts go into your profile. Tap to answer.': 'এই ডিভাইসের ওয়ার্কআউটগুলো আপনার প্রোফাইলে যাবে কি না না বলা পর্যন্ত কিছুই সিঙ্ক হবে না। উত্তর দিতে ট্যাপ করুন।',
