  // --- AI Coach: why a job failed or was refused (lib/coach-api.js JOB_ERRORS, BYOK_ERRORS) ---
  'The Coach isn’t set up on this instance.': 'এই সার্ভারে কোচ সেট আপ করা নেই।',
  'The Coach is taking a rest day. Try again tomorrow.': 'কোচ আজ বিশ্রামের দিনে আছে। কাল আবার চেষ্টা করুন।',
  'The Coach took too long and gave up.': 'কোচ অনেক সময় নিয়েছে এবং হাল ছেড়ে দিয়েছে।',
  'The Coach couldn’t sign in to its provider. The instance owner needs to check its setup.': 'কোচ তার প্রোভাইডারে সাইন ইন করতে পারেনি। সার্ভারের মালিককে এর সেটআপ দেখতে হবে।',
  'The Coach isn’t installed properly on this instance.': 'এই সার্ভারে কোচ ঠিকমতো ইনস্টল করা নেই।',
  'The Coach couldn’t run. The instance owner needs to check its setup.': 'কোচ চালানো যায়নি। সার্ভারের মালিককে এর সেটআপ দেখতে হবে।',
  'The Coach hit its AI provider’s limit. Try again later, or the instance owner needs to check the plan or key.': 'কোচ তার AI প্রদানকারীর সীমায় পৌঁছে গেছে। পরে আবার চেষ্টা করুন, না হলে সার্ভারের মালিককে প্ল্যান বা কী দেখতে হবে।',
  'The Coach’s AI provider rejected the request format. The instance owner needs to try another model.': 'কোচের AI প্রদানকারী অনুরোধের ফরম্যাট ফিরিয়ে দিয়েছে। সার্ভারের মালিককে অন্য একটি মডেল চেষ্টা করতে হবে।',
  'The Coach’s AI provider is having an outage. Try again in a little while.': 'কোচের AI প্রদানকারী এখন বিভ্রাটে আছে। একটু পরে আবার চেষ্টা করুন।',
  'The Coach couldn’t reach its AI provider. The instance owner needs to check the endpoint and the network.': 'কোচ তার AI প্রদানকারীর কাছে পৌঁছাতে পারেনি। সার্ভারের মালিককে এন্ডপয়েন্ট আর নেটওয়ার্ক দেখতে হবে।',
  'The Coach answered with something the app couldn’t use.': 'কোচ এমন উত্তর দিয়েছে যা অ্যাপ ব্যবহার করতে পারেনি।',
  'The server restarted while the Coach was thinking.': 'কোচ ভাবার সময় সার্ভার রিস্টার্ট হয়েছে।',
  'The Coach couldn’t read your training data.': 'কোচ আপনার ট্রেনিং ডেটা পড়তে পারেনি।',
  'The Coach is switched off on this instance for safety reasons.': 'নিরাপত্তার কারণে এই সার্ভারে কোচ বন্ধ রাখা হয়েছে।',
  'Something went wrong on the server.': 'সার্ভারে কিছু একটা ভুল হয়েছে।',
  'Your AI provider rejected the key on this phone. Check it under Settings → AI Coach.': 'আপনার AI প্রোভাইডার এই ফোনের কী প্রত্যাখ্যান করেছে। সেটিংস → AI কোচ-এ চেক করুন।',
