  'That looks too heavy. Keep it at {0} or less.': 'এটি খুব ভারী মনে হচ্ছে। {0} বা তার কম রাখুন।',
  'That’s still in the future. Try an earlier start.': 'এটি এখনও ভবিষ্যতে। আরও আগের শুরুর সময় চেষ্টা করুন।',
  'That’s more than a day. Keep it to 24 hours or less.': 'এটি এক দিনের বেশি। ২৪ ঘণ্টা বা তার কম রাখুন।',
