  'The first set goes up when every set reaches its reps, and the rest follow it.': 'প্রতিটি সেটে রেপ পূরণ হলে প্রথম সেটের ওজন বাড়ে, বাকিগুলোও সেই অনুযায়ী বাড়ে।',
