  'Top of the range on all {0} sets. {1} {2} more, back to {3} sets of {4}.': '{0}টি সেটেই রেঞ্জের শীর্ষ। আরও {1} {2}, আবার {3} সেট × {4}।',
  'Top of the range on all {0} sets. {1} {2} less help, back to {3} sets of {4}.': '{0}টি সেটেই রেঞ্জের শীর্ষ। {1} {2} কম সহায়তা, আবার {3} সেট × {4}।',
  'Short of the target, but more reps than before. Same sets and reps again.': 'লক্ষ্যের চেয়ে একটু কম, তবে আগের চেয়ে বেশি রেপ। আবার একই সেট ও রেপ।',
  'Missed reps last time. Same sets and reps again ({0} of {1} to go).': 'গতবার রেপ বাদ গেছে। আবার একই সেট ও রেপ ({1}-এর মধ্যে {0} বাকি)।',
  'Stuck for {0} sessions. Deload to {1} {2} and start again at {3} sets of {4}.': '{0}টি সেশন আটকে আছেন। {1} {2}-এ ডিলোড করুন, আবার {3} সেট × {4} থেকে শুরু।',
