  'To answer, the Coach sends this through your openGym server to {0}, an AI service outside openGym that your server’s admin picked:': 'উত্তর দিতে কোচ এটি আপনার openGym সার্ভারের মাধ্যমে {0}-এ পাঠায়। এটি openGym-এর বাইরের একটি AI সার্ভিস, যা আপনার সার্ভারের অ্যাডমিন বেছে নিয়েছেন:',
  'To answer, this device sends this straight to {0}, an AI service outside openGym, with your API key:': 'উত্তর দিতে এই ডিভাইস আপনার API কী দিয়ে এটি সরাসরি {0}-এ পাঠায়। এটি openGym-এর বাইরের একটি AI সার্ভিস:',
  'Who may see your training': 'কে আপনার ট্রেনিং দেখতে পারে',
  'Who the Coach may send your training to from this device. Withdraw it and the Coach asks again next time. A model on your own network never needs asking.': 'এই ডিভাইস থেকে কোচ কাকে আপনার ট্রেনিং পাঠাতে পারে। অনুমতি তুলে নিলে কোচ পরের বার আবার জিজ্ঞেস করবে। আপনার নিজের নেটওয়ার্কের মডেলের জন্য কখনও অনুমতি লাগে না।',
  'With your API key': 'আপনার API কী দিয়ে',
  'Withdraw': 'অনুমতি তুলে নিন',
  'Withdrawn. The Coach will ask before it sends anything again.': 'অনুমতি তুলে নেওয়া হয়েছে। আবার কিছু পাঠানোর আগে কোচ জিজ্ঞেস করবে।',
  'Your answers to the Coach: goal, days, equipment, limits and injuries': 'কোচকে দেওয়া আপনার উত্তর: লক্ষ্য, দিন, ইকুইপমেন্ট, সীমাবদ্ধতা ও চোট',
  'Your body weight and goal weight': 'আপনার শরীরের ওজন ও লক্ষ্য ওজন',
  'Your data, your call': 'আপনার ডেটা, আপনার সিদ্ধান্ত',
  'Your name, email and sign-in stay put. {0} handles the rest under its own privacy terms.': 'আপনার নাম, ই-মেইল ও সাইন-ইন তথ্য এখানেই থাকে। বাকিটা {0} তার নিজের প্রাইভেসি নীতি অনুযায়ী সামলায়।',
