  'Delete forever': 'চিরতরে মুছুন',
  'That is not your account name.': 'এটি আপনার অ্যাকাউন্টের নাম নয়।',
  'You’re the only admin here, and other profiles still use this server. Make someone else an admin first.': 'আপনি এখানে একমাত্র অ্যাডমিন, আর অন্য প্রোফাইলগুলো এখনও এই সার্ভার ব্যবহার করছে। আগে অন্য কাউকে অ্যাডমিন করুন।',
  'Couldn’t delete the account. Nothing was removed.': 'অ্যাকাউন্ট মোছা যায়নি। কিছুই সরানো হয়নি।',
  'Your account is gone. Thanks for every rep.': 'আপনার অ্যাকাউন্ট মুছে গেছে। প্রতিটি রেপের জন্য ধন্যবাদ।',
  'Confirm it’s you to delete your openGym account': 'আপনার openGym অ্যাকাউন্ট মুছতে নিশ্চিত করুন যে এটি আপনিই',
  'Not confirmed on this phone. Nothing was deleted.': 'এই ফোনে নিশ্চিত হয়নি। কিছুই মোছা হয়নি।',
  'This phone has no screen lock, so the name you typed is the only check.': 'এই ফোনে কোনো স্ক্রিন লক নেই, তাই আপনার লেখা নামটিই একমাত্র চেক।',
  'Your phone checks that it’s you (face, fingerprint or passcode), then the account is deleted.': 'আপনার ফোন চেক করবে যে এটি আপনিই (মুখ, আঙুলের ছাপ বা পাসকোড), তারপর অ্যাকাউন্ট মুছে যাবে।',
  // --- first-start permission steps ---
  'Never miss the end of a rest': 'বিশ্রামের শেষ আর কখনো মিস করবেন না',
  'One quick thing': 'ছোট্ট একটি কথা',
  'Rest timer, right on the lock screen': 'বিশ্রামের টাইমার, সরাসরি লক স্ক্রিনে',
  'Training reminders, only if you switch them on': 'ট্রেনিংয়ের রিমাইন্ডার, শুধু আপনি চালু করলে',
  'You can change it anytime in your phone’s settings.': 'ফোনের সেটিংসে যেকোনো সময় এটি বদলাতে পারেন।',
  'openGym can tap you on the shoulder when a rest is over, even with the phone locked in your pocket.': 'ফোন লক করে পকেটে রাখলেও বিশ্রাম শেষ হলে openGym আপনাকে জানিয়ে দিতে পারে।',
