  'Not downloaded': 'ডাউনলোড হয়নি',
  'On this device': 'এই ডিভাইসে',
  'Sharper animations aren’t available on this device yet. The built-in ones work everywhere.': 'আরও শার্প অ্যানিমেশন এই ডিভাইসে এখনও পাওয়া যায় না। বিল্ট-ইনগুলো সব জায়গায় চলে।',
  'Sharper animations come only through the app stores. This APK keeps the ones built into it.': 'আরও স্পষ্ট অ্যানিমেশন শুধু অ্যাপ স্টোরের মাধ্যমে আসে। এই APK তার ভেতরের অ্যানিমেশনগুলোই রাখে।',
  'Sharper animations download once per figure. Until they’re here you see the built-in ones, so nothing ever goes blank.': 'আরও শার্প অ্যানিমেশন প্রতিটি ফিগারের জন্য একবার ডাউনলোড হয়। ডাউনলোড না হওয়া পর্যন্ত বিল্ট-ইনগুলো দেখবেন, তাই কিছুই ফাঁকা থাকে না।',
