  'Rest between warm-ups': 'ওয়ার্ম-আপের মাঝে বিশ্রাম',
  'Warm-ups are light, so they can rest less, or not at all. The last one still gets the full rest before your first work set.': 'ওয়ার্ম-আপ হালকা, তাই বিশ্রাম কম হলেও চলে, এমনকি না হলেও। তবে শেষটির পর প্রথম ওয়ার্কিং সেটের আগে পুরো বিশ্রাম থাকে।',
