  'Set the bar once for every exercise of a type.': 'একই ধরনের সব ব্যায়ামের জন্য বার একবারই সেট করুন।',
  'Your bar for this type, set in Your bars.': 'এই ধরনের জন্য আপনার বার, “আপনার বার”-এ সেট করা।',
  'What the bars at your gym weigh. Every exercise with that bar counts plates from it, unless you gave the exercise its own. Logged weights stay totals.': 'আপনার জিমের বারগুলোর ওজন কত। ওই বারের প্রতিটি ব্যায়াম এখান থেকে প্লেট গোনে, যদি না ব্যায়ামটিকে আলাদা বার দিয়ে থাকেন। লগ করা ওজন মোট ওজনই থাকে।',
  'Most lifts in the library use “{0}”, a few use “{1}”. A short bar for all of them means setting both.': 'লাইব্রেরির বেশিরভাগ ব্যায়াম “{0}” ব্যবহার করে, কয়েকটি “{1}”। সবগুলোর জন্য ছোট বার চাইলে দুটোই সেট করুন।',
  'Back to the standard bars': 'স্ট্যান্ডার্ড বারে ফিরে যান',
  'Standard bars. Tap if yours are lighter.': 'স্ট্যান্ডার্ড বার। আপনারগুলো হালকা হলে ট্যাপ করুন।',
  'The last warm-up still gets the full rest before your first work set.': 'শেষ ওয়ার্ম-আপ সেটের পরেও প্রথম ওয়ার্কিং সেটের আগে পুরো বিশ্রাম থাকে।',
