  'Not trained:': 'ট্রেন করা হয়নি:',
  'Rounded to whole sets. A set counts fully for its main muscle and partly for the ones that help, so the muscles add up to more than your work sets.': 'পুরো সেটে রাউন্ড করা। একটি সেট প্রধান পেশির জন্য পুরোটা আর সহায়ক পেশিগুলোর জন্য আংশিক গোনা হয়, তাই পেশিগুলোর যোগফল আপনার ওয়ার্কিং সেটের চেয়ে বেশি হয়।',
  'One session in this period.': 'এই সময়ে একটি সেশন।',
