  'Your training on paper: totals, charts, new bests and every set. Frame it, print it or send it to your coach.': 'কাগজে আপনার ট্রেনিং: মোট হিসাব, চার্ট, নতুন রেকর্ড আর প্রতিটি সেট। ফ্রেমে বাঁধান, প্রিন্ট করুন বা কোচকে পাঠান।',
