  "A few more weigh-ins, spread over the next days, and you get a weekly trend.": "আগামী কয়েক দিনে আরও কয়েকবার ওজন মাপুন, তাহলে সাপ্তাহিক ট্রেন্ড পাবেন।",
  "On pace": "ঠিক গতিতে আছেন",
  "Slower than planned": "পরিকল্পনার চেয়ে ধীর",
  "Gaining faster than planned": "পরিকল্পনার চেয়ে দ্রুত বাড়ছে",
  "Losing faster than planned": "পরিকল্পনার চেয়ে দ্রুত কমছে",
  "Outside your range": "আপনার রেঞ্জের বাইরে",
  "Enter a range first": "আগে একটি রেঞ্জ দিন",
  "The trend through your weigh-ins of the last 3 weeks, so one salty dinner does not move it. Give it a range and the card tells you whether you are on pace.": "গত ৩ সপ্তাহের ওজন মাপা থেকে ট্রেন্ড, তাই এক রাতে বেশি লবণ খেলেও এটি নড়ে না। একটি রেঞ্জ দিন, কার্ড জানাবে আপনি ঠিক গতিতে আছেন কি না।",
  "Lose": "কমানো",
  "Gain": "বাড়ানো",
  "Hold": "ধরে রাখা",
  "% of body weight": "শরীরের ওজনের %",
  "Within ±": "± এর মধ্যে",
  "Hold within ±{0} a week.": "সপ্তাহে ±{0}-এর মধ্যে ধরে রাখা।",
  "Lose {0} to {1} a week.": "সপ্তাহে {0} থেকে {1} কমানো।",
  "Gain {0} to {1} a week.": "সপ্তাহে {0} থেকে {1} বাড়ানো।",
  "A cut is often 0.5 to 1 % a week, a lean bulk 0.25 to 0.5 %.": "কাটিংয়ে সাধারণত সপ্তাহে ০.৫ থেকে ১ %, লিন বাল্কে ০.২৫ থেকে ০.৫ %।",
  "Remove range": "রেঞ্জ সরান",
  'Admin': 'অ্যাডমিন',
  'Heaviest set as a share of body weight, per workout': 'প্রতি ওয়ার্কআউটে শরীরের ওজনের অনুপাতে সবচেয়ে ভারী সেট',
  'Estimated 1RM as a share of body weight, per workout': 'প্রতি ওয়ার্কআউটে শরীরের ওজনের অনুপাতে আনুমানিক 1RM',
  'Body weight over this period: {0} → {1}. Bodyweight and assisted exercises count your body weight as part of the load.': 'এই সময়ে শরীরের ওজন: {0} → {1}। বডিওয়েট ও অ্যাসিস্টেড ব্যায়ামে আপনার শরীরের ওজন লোডের অংশ হিসেবে ধরা হয়।',
  'Weight stack': 'ওজনের স্ট্যাক',
  'The weights this machine really has, odd steps and all. Progression, deloads, warm-ups and the + and − buttons land only on these.': 'এই মেশিনে আসলে যে ওজনগুলো আছে, অসমান ধাপসহ। প্রগ্রেশন, ডিলোড, ওয়ার্ম-আপ আর + ও − বোতাম শুধু এগুলোতেই থামে।',
  'No list yet, so this exercise steps by its increment as usual.': 'এখনও কোনো তালিকা নেই, তাই এই ব্যায়াম আগের মতো নিজের ধাপে বাড়ে।',
  'First ({0})': 'প্রথম ({0})',
  'How many': 'কতগুলো',
  'Fill in': 'পূরণ করুন',
  'That’s the whole stack: {0} {1} is the heaviest it goes, so the weight stays.': 'এটিই পুরো স্ট্যাক: সবচেয়ে ভারী {0} {1}, তাই ওজন একই থাকছে।',
  'No code on your phone? It only has one while it’s connected to this server: Settings → Account → Connect to my server.': 'ফোনে কোনো কোড নেই? এই সার্ভারে সংযুক্ত থাকলেই কেবল কোড থাকে: সেটিংস → অ্যাকাউন্ট → আমার সার্ভারে সংযোগ করুন।',
  'Signing in on your computer too needs your own server. Connect this phone to it, and Add another device then gives the computer a code.': 'কম্পিউটারেও সাইন ইন করতে আপনার নিজের সার্ভার লাগবে। এই ফোনটি সেখানে সংযুক্ত করুন, তারপর “আরেকটি ডিভাইস যোগ করুন” কম্পিউটারের জন্য একটি কোড দেবে।',
  'How hard it felt': 'কতটা কঠিন লাগল',
  'Not rated yet': 'এখনও রেট করা হয়নি',
  'How hard did that feel?': 'এটি কতটা কঠিন লাগল?',
  'Tap how it felt, or type an exact {0}.': 'কেমন লাগল তাতে ট্যাপ করুন, অথবা সঠিক {0} লিখুন।',
  'All out, nothing left': 'সব দিয়ে দিয়েছি, কিছু বাকি নেই',
  'Nearly all out': 'প্রায় সর্বোচ্চ',
  'Very hard, one word at a time': 'খুব কঠিন, একটা একটা শব্দ বলা যায়',
  'Hard, short sentences only': 'কঠিন, শুধু ছোট বাক্য বলা যায়',
  'Working, but steady': 'পরিশ্রম হচ্ছে, তবে স্থিরভাবে',
