  'No schedule yet. Put routines on your week or in a loop in Plan, then take it over here.': 'এখনও কোনো সময়সূচি নেই। প্ল্যানে আপনার সপ্তাহে বা লুপে রুটিন রাখুন, তারপর এখানে নিয়ে আসুন।',
