  "Finish saves the session and moves your weights along. This practice one just quietly disappears.": "“শেষ করুন” সেশনটি সেভ করে এবং আপনার ওজন এগিয়ে নেয়। এই প্র্যাকটিস ওয়ার্কআউট চুপচাপ মুছে যাবে।",
