  "Programmes, starter plans and sharing a plan with a friend live behind this button.": "প্রোগ্রাম, স্টার্টার প্ল্যান আর বন্ধুর সাথে প্ল্যান শেয়ার, সবই এই বোতামের পেছনে।",
  "Records": "রেকর্ড",
  "Schedule says when, Routines says what. Build your own or grab a starter plan.": "সূচি বলে কখন, রুটিন বলে কী। নিজেরটা তৈরি করুন বা একটি স্টার্টার প্ল্যান নিন।",
  "Search thousands of exercises in your language. Star your favourites and they float to the top.": "আপনার ভাষায় হাজারো ব্যায়াম খুঁজুন। প্রিয়গুলোতে স্টার দিন, সেগুলো উপরে চলে আসবে।",
  "See which muscles got the work and which still need rest. Tap one for details.": "দেখুন কোন পেশিতে কাজ হয়েছে আর কোনগুলোর এখনও বিশ্রাম দরকার। বিস্তারিত দেখতে একটিতে ট্যাপ করুন।",
  "Show me": "দেখান",
  "Show the tour again": "ট্যুর আবার দেখান",
  "Skip tour": "ট্যুর এড়িয়ে যান",
  "Step {0} of {1}": "ধাপ {0} / {1}",
  "Swipe a set": "সেট সোয়াইপ করুন",
  "Swipe a set sideways to copy or remove it. Its number opens even more.": "কপি করতে বা সরাতে সেটটি পাশে সোয়াইপ করুন। সেটের নম্বরে ট্যাপ করলে আরও অপশন পাবেন।",
  "The big Start button": "বড় “শুরু” বোতাম",
  "The little body shows what each day works, so leg day can’t hide.": "ছোট্ট শরীরের ছবিটি দেখায় কোন দিন কোন পেশির কাজ, তাই লেগ ডে লুকাতে পারবে না।",
  "The rest timer starts by itself. Add time, or skip it if you feel heroic.": "রেস্ট টাইমার নিজে থেকেই শুরু হয়। সময় বাড়ান, অথবা খুব সাহসী লাগলে এড়িয়ে যান।",
  "The ⋯ menu": "⋯ মেনু",
  "Theme, accent colour and what Home shows.": "থিম, অ্যাকসেন্ট রং আর হোমে কী দেখাবে।",
  "This one is pretend, nothing gets saved. Each row is a set: weight, then reps. Tap a number to change it.": "এটি শুধু প্র্যাকটিস, কিছুই সেভ হবে না। প্রতিটি সারি একটি সেট: ওজন, তারপর রেপ। বদলাতে একটি সংখ্যায় ট্যাপ করুন।",
  "Tick it off": "টিক দিন",
  "Today at a glance": "এক নজরে আজ",
  "Today’s session lives here. One tap and you’re lifting. On a rest day it says so, no guilt trip.": "আজকের সেশন এখানে। এক ট্যাপেই ওজন তোলা শুরু। বিশ্রামের দিনে সেটাই লেখা থাকে, কোনো খোঁটা ছাড়াই।",
  "Train on fixed weekdays, or run your routines in a loop where the next one waits for you.": "নির্দিষ্ট দিনে ট্রেন করুন, অথবা রুটিন লুপে চালান, যেখানে পরেরটি আপনার জন্য অপেক্ষা করে।",
  "Want a 1-minute tour?": "১ মিনিটের একটি ট্যুর দেখবেন?",
  "Week or rotation": "সপ্তাহ বা রোটেশন",
  "We’ll point at the good bits on the real screens. Bail out anytime.": "আসল স্ক্রিনগুলোতেই দরকারি জিনিসগুলো দেখিয়ে দেব। যখন খুশি বেরিয়ে যেতে পারেন।",
  "Workout settings, layouts, notes and extra exercises hide in here.": "ওয়ার্কআউট সেটিংস, লেআউট, নোট আর বাড়তি ব্যায়াম এখানে লুকানো।",
  "Workouts, streaks and everything you’ve lifted. It fills up as you train.": "ওয়ার্কআউট, স্ট্রিক আর যা কিছু তুলেছেন। ট্রেন করতে করতে ভরে ওঠে।",
  "You stopped halfway. Want to see the rest?": "আপনি মাঝপথে থেমেছিলেন। বাকিটা দেখবেন?",
