  'A small picture next to each exercise, like a plan from the gym.': 'প্রতিটি ব্যায়ামের পাশে একটি ছোট ছবি, জিমের দেওয়া প্ল্যানের মতো।',
  // --- Settings → Integrations (1.4.4) ---
  "This one lives in the openGym phone app: Apple Health on iPhone, Health Connect on Android.": "এটি ফোনের openGym অ্যাপে থাকে: iPhone-এ Apple Health, Android-এ Health Connect।",
  "Webhooks are sent by your own openGym server, so they need one. Connect this device to it in Account.": "ওয়েবহুক পাঠায় আপনার নিজের openGym সার্ভার, তাই একটি সার্ভার লাগবে। অ্যাকাউন্টে গিয়ে এই ডিভাইসটি যুক্ত করুন।",
  "Webhooks are off on this server. Add INTEGRATIONS=webhook to its .env and restart it.": "এই সার্ভারে ওয়েবহুক বন্ধ। এর .env-এ INTEGRATIONS=webhook যোগ করে আবার চালু করুন।",
  "The MCP server runs next to your own openGym server and reads your data there.": "MCP সার্ভার আপনার openGym সার্ভারের পাশে চলে এবং সেখান থেকেই আপনার ডেটা পড়ে।",
  "Only what you switch on talks to anything. The rest stays out of your way.": "শুধু যা আপনি চালু করবেন, সেটিই বাইরে যোগাযোগ করে। বাকিগুলো আপনাকে বিরক্ত করবে না।",
  "Could not reach your server": "আপনার সার্ভারে পৌঁছানো যায়নি",
  "Tap to try again": "আবার চেষ্টা করতে ট্যাপ করুন",
  "Disconnect {0}?": "{0}-এর সংযোগ বিচ্ছিন্ন করবেন?",
  "openGym stops writing and reading. What it already wrote can stay there as your data, or go.": "openGym লেখা ও পড়া বন্ধ করবে। আগে যা লিখেছে তা আপনার ডেটা হিসেবে থাকতে পারে, অথবা মুছে যেতে পারে।",
  "Works with": "যেগুলোর সাথে কাজ করে",
  "No extra connection needed: they write to {0}, and openGym reads from there.": "আলাদা সংযোগ লাগবে না: এরা {0}-এ লেখে, আর openGym সেখান থেকে পড়ে।",
  "No extra connection needed: they write to Apple Health or Health Connect, and the openGym phone app reads from there.": "আলাদা সংযোগ লাগবে না: এরা Apple Health বা Health Connect-এ লেখে, আর ফোনের openGym অ্যাপ সেখান থেকে পড়ে।",
  "{0} has no direct line to openGym, and it does not need one.": "{0}-এর সাথে openGym-এর সরাসরি সংযোগ নেই, আর দরকারও নেই।",
  "How it gets here": "এখানে কীভাবে আসে",
