  "Bar": "বার",
  "Body": "শরীর",
  "Built from your work weight and rounded to this gym’s plates and dumbbells. An exercise can pick its own in its settings.": "আপনার ওয়ার্কিং ওজন থেকে তৈরি, এই জিমের প্লেট আর ডাম্বেল অনুযায়ী রাউন্ড করা। কোনো ব্যায়াম তার সেটিংসে নিজের নিয়ম বেছে নিতে পারে।",
