  "It hurts, it’s taken, no time, feeling great": "ব্যথা, মেশিন খালি নেই, সময় নেই, দারুণ লাগছে",
  "It pinches, so lighter for the rest of it. Stop if it still hurts.": "টান লাগছে, তাই বাকিটা হালকা করে। এখনও ব্যথা হলে থামুন।",
  "It pinches, so the sets you have left go to a movement that loads the same muscle from a kinder angle.": "টান লাগছে, তাই বাকি সেটগুলো এমন একটি ব্যায়ামে যাবে, যা একই পেশিকে আরেকটু আরামদায়ক কোণ থেকে কাজ করায়।",
  "Keep these warm-ups": "এই ওয়ার্ম-আপগুলো রাখুন",
  "Kept. Same warm-ups next time, scaled to your work weight.": "রাখা হলো। পরের বার একই ওয়ার্ম-আপ, আপনার ওয়ার্কিং ওজন অনুযায়ী।",
  "Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "লগ করা সেট আর আপনার রুটিন যেমন আছে তেমনই থাকবে। কোচ ডাক্তার বা ফিজিওথেরাপিস্ট নয়। কোথাও ব্যথা হলে একজন পেশাদারের পরামর্শ নিন।",
  "Looking at your workout…": "আপনার ওয়ার্কআউট দেখছি…",
  "Machine’s taken": "মেশিন খালি নেই",
  "My own": "আমার নিজের",
  "New programme “{0}”": "নতুন প্রোগ্রাম “{0}”",
  "Nothing at {0} {1}: that one starts cold.": "{0} {1}-এ কোনো ওয়ার্ম-আপ নেই: এটি সরাসরি শুরু হয়।",
  "Nothing could be applied any more.": "আর কিছুই প্রয়োগ করা যায়নি।",
  "Nothing to change. Carry on as planned.": "বদলানোর কিছু নেই। পরিকল্পনা মতো চালিয়ে যান।",
  "One set less keeps the session doable today and still counts.": "একটি সেট কম করলে আজকের সেশন করা সম্ভব হয়, আর সেটিও গোনা হয়।",
  "Only the warm-ups you plan yourself.": "শুধু আপনার নিজের প্ল্যান করা ওয়ার্ম-আপ।",
  "Ramped from the work weight: more rungs when it is heavy, fewer when it is light.": "ওয়ার্কিং ওজন থেকে ধাপে ধাপে: ভারী হলে বেশি ধাপ, হালকা হলে কম।",
  "Remove warm-up {0}": "ওয়ার্ম-আপ {0} সরান",
