  "Routines, exercises, sets and reps, warm-ups, programmes, your weekly schedule, progression settings and what your gym can load.": "রুটিন, ব্যায়াম, সেট ও রেপ, ওয়ার্ম-আপ, প্রোগ্রাম, আপনার সাপ্তাহিক সূচি, প্রগ্রেশন সেটিংস আর আপনার জিমে কত ওজন লোড করা যায়।",
