  "Saved under Plan → Programmes. It starts when you start it.": "প্ল্যান → প্রোগ্রামে সেভ হয়েছে। আপনি শুরু করলেই শুরু হবে।",
  "Short on time": "সময় কম",
  "Skip the rest of {0}": "{0}-এর বাকিটা বাদ দিন",
  "Something else": "অন্য কিছু",
  "Squats, presses, rows and friends get a ramp. Curls and raises start cold.": "স্কোয়াট, প্রেস, রো এই ধরনের ব্যায়ামে র‍্যাম্প হয়। কার্ল আর রেইজ সরাসরি শুরু হয়।",
  "Straight into the work sets.": "সরাসরি ওয়ার্কিং সেটে।",
  "That workout is over, so these can’t be applied any more.": "সেই ওয়ার্কআউট শেষ, তাই এগুলো আর প্রয়োগ করা যাবে না।",
  "The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.": "অ্যাপ আপনার ওয়ার্কিং ওজন থেকে ধাপে ধাপে বাড়ায়: ভারী হলে বেশি ওয়ার্ম-আপ সেট, হালকা হলে কম, আপনার জিমের প্লেট অনুযায়ী।",
  "The rack is taken, so do it at the end. The rest of the session does not need it.": "র‍্যাক খালি নেই, তাই এটি শেষে করুন। সেশনের বাকিটায় র‍্যাক লাগবে না।",
  "There’s no workout running.": "কোনো ওয়ার্কআউট চলছে না।",
  "These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.": "এই ওয়ার্ম-আপগুলো প্রতিটি সেশনে ওয়ার্কিং সেটের আগে আসে, ওয়ার্কিং ওজনের অংশ হিসেবে, তাই সেটির সাথে বাড়ে।",
  "This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.": "এটি ডেমো, তাই আমার পেছনে কোনো AI মডেল নেই। আপনার নিজের সার্ভারে আমি আপনার সেশন দেখে এমন পরিবর্তনের পরামর্শ দিই।",
  "Warm-up {0}": "ওয়ার্ম-আপ {0}",
  "Warm-ups": "ওয়ার্ম-আপ",
  "What’s up? The Coach suggests a few changes to what is left of this workout. Logged sets stay as they are.": "কী হয়েছে? কোচ এই ওয়ার্কআউটের বাকি অংশে কয়েকটি পরিবর্তনের পরামর্শ দেবে। লগ করা সেট যেমন আছে তেমনই থাকবে।",
  "Where, and what movement hurts? (optional)": "কোথায়, আর কোন নড়াচড়ায় ব্যথা? (অপশনাল)",
  "With {0} {1} today: {2}": "আজ {0} {1} হলে: {2}",
  "You can keep training, the answer waits here and in the Coach.": "আপনি ট্রেনিং চালিয়ে যেতে পারেন, উত্তর এখানে আর কোচে অপেক্ষা করবে।",
  "You feel strong, so a little more on the bar for what is left. Not a new max, just a nudge.": "আপনি শক্তিশালী বোধ করছেন, তাই বাকিটায় বারে একটু বেশি ওজন। নতুন ম্যাক্স নয়, শুধু একটু বাড়তি।",
  "Your rows, as a share of the work weight, so they grow with it.": "আপনার ওয়ার্ম-আপ সারিগুলো ওয়ার্কিং ওজনের অংশ হিসেবে, তাই সেটির সাথে বাড়ে।",
