  "Or any emoji": "অথবা যেকোনো ইমোজি",
  "Reset to default": "ডিফল্টে ফিরুন",
  "Rocket": "রকেট",
  "Shield": "ঢাল",
  "Snowflake": "তুষারকণা",
  "Star": "তারা",
  "Still open": "এখনো খোলা",
  "Still open. One workout and it counts.": "এখনো খোলা। একটি ওয়ার্কআউট হলেই গোনা হবে।",
  "Streak flame": "স্ট্রিকের শিখা",
  "Streak freeze": "স্ট্রিক ফ্রিজ",
  "Sun": "সূর্য",
  "Tap a week's mark to see how it counted.": "কোনো সপ্তাহ কীভাবে গোনা হলো দেখতে তার চিহ্নে ট্যাপ করুন।",
  "That one is not an emoji. Any emoji works, letters do not.": "এটা ইমোজি নয়। যেকোনো ইমোজি চলবে, অক্ষর নয়।",
  "The colors around it follow your pick, in light and dark.": "চারপাশের রং আপনার পছন্দ অনুযায়ী বদলায়, লাইট ও ডার্ক দুটোতেই।",
  "This week stays open until it ends. No pressure yet.": "এই সপ্তাহ শেষ না হওয়া পর্যন্ত খোলা থাকবে। এখনো তাড়া নেই।",
  "Tree": "গাছ",
