  "Weeks in a row with at least one workout.": "টানা যত সপ্তাহে অন্তত একটি ওয়ার্কআউট হয়েছে।",
  "You trained, so this week counts. Streak: {0}.": "আপনি ট্রেনিং করেছেন, তাই এই সপ্তাহ গোনা হলো। স্ট্রিক: {0}।",
