  "Door {0}, open and lit": "{0} নম্বর দরজা, খোলা আর আলোকিত",
  "Every door you open hangs a bauble. Train that day, or do what is behind the door, and it lights up.": "প্রতিটি দরজা খুললে একটা বাউবল ঝোলে। সেদিন ট্রেনিং করো, বা দরজার পেছনের কাজটা করো, তাহলে সেটা জ্বলে উঠবে।",
  "Festive flame": "উৎসবের শিখা",
