  "Not quite a reindeer yet. Plenty of December left.": "এখনও পুরো রেনডিয়ার হওনি। ডিসেম্বর এখনও অনেক বাকি।",
  "Open door {0}": "{0} নম্বর দরজা খোলো",
  "Put it on": "পরে নাও",
  "Spread them over the day. Every {0} counts.": "পুরো দিনে ছড়িয়ে দাও। প্রতিটি {0} গোনা হবে।",
  "Start a workout with it": "এটা দিয়ে ওয়ার্কআউট শুরু করো",
  "Start the finisher": "ফিনিশার শুরু করো",
  "Swipe the door open, or give it a tap": "দরজাটা সোয়াইপ করে খোলো, বা একটা ট্যাপ দাও",
  "Take {0} back": "{0} ফেরত নাও",
  "Time trained: {0}": "ট্রেনিংয়ের সময়: {0}",
  "Train today, or do this, and its bauble lights up.": "আজ ট্রেনিং করো, বা এটা করো, তাহলে এর বাউবল জ্বলবে।",
  "Wearing it. Very merry.": "পরে আছ। দারুণ জমকালো।",
  "Weeks in a row with at least one workout. The elves are taking notes.": "টানা যত সপ্তাহে অন্তত একটা ওয়ার্কআউট হয়েছে। এল্ফরা নোট নিচ্ছে।",
