  "Carry the shopping like it owes you money. Tall chest, slow steps.": "বাজারের ব্যাগ এমনভাবে বও যেন ওটা তোমার কাছে টাকা পায়। বুক টান, পা ধীরে।",
  "You found Rudolph! He says hi and hides again. New spot tomorrow.": "তুমি রুডলফকে খুঁজে পেয়েছ! সে হাই বলে আবার লুকিয়ে পড়ে। কাল নতুন জায়গা।",
