  "Missed plan": "বাদ পড়া পরিকল্পনা",
  "Open this day": "এই দিনটি খুলুন",
  "Planned, not trained. Any other day this week still counts.": "পরিকল্পনা ছিল, ট্রেনিং হয়নি। এই সপ্তাহের অন্য যেকোনো দিন এখনো গোনা হবে।",
  "Planned, not trained. Any workout that week would have counted.": "পরিকল্পনা ছিল, ট্রেনিং হয়নি। সেই সপ্তাহে যেকোনো ওয়ার্কআউট গোনা হতো।",
  "Planned, not trained. No harm done: you trained another day that week, so it still counts.": "পরিকল্পনা ছিল, ট্রেনিং হয়নি। সমস্যা নেই: আপনি অন্য দিন ট্রেনিং করেছেন, তাই সপ্তাহটি তবুও গোনা হয়েছে।",
  "Bank 1 freeze, earned every 4 trained weeks. Two missed weeks in a row end the streak.": "১টি ফ্রিজ জমা, প্রতি ৪ ট্রেনিং-সপ্তাহে একটি। টানা দুই সপ্তাহ বাদ গেলে স্ট্রিক শেষ।",
  "Bank up to 2 freezes, one every 4 trained weeks. Even two missed weeks in a row can be covered.": "২টি পর্যন্ত ফ্রিজ জমা, প্রতি ৪ ট্রেনিং-সপ্তাহে একটি। টানা দুই সপ্তাহ বাদ গেলেও ঢাকা যায়।",
  "Change the freeze rule": "ফ্রিজের নিয়ম বদলান",
  "Every 4th week you train earns a freeze. You can bank 1.": "প্রতি চতুর্থ ট্রেনিং-সপ্তাহে একটি ফ্রিজ পাবেন। ১টি জমানো যায়।",
  "Every week counts. Miss one and the streak starts over.": "প্রতিটি সপ্তাহ গোনা হয়। একটি বাদ গেলে স্ট্রিক আবার শুরু।",
  "From now on: {0}.": "এখন থেকে: {0}।",
  "From the week of {0} on: {1}.": "{0}-এর সপ্তাহ থেকে: {1}।",
  "Generous": "উদার",
  "Gentle": "নরম",
  "How forgiving should your week streak be?": "আপনার সাপ্তাহিক স্ট্রিক কতটা ক্ষমাশীল হবে?",
  "How strict should your streak be?": "আপনার স্ট্রিক কতটা কড়া হবে?",
  "Miss a week and a freeze covers it: the streak keeps going, that week just adds nothing. Two missed weeks in a row, and it starts over.": "একটি সপ্তাহ বাদ গেছে? একটি ফ্রিজ সেটা ঢেকে দেয়: স্ট্রিক চলতে থাকে, শুধু সেই সপ্তাহ কিছু যোগ করে না। টানা দুই সপ্তাহ বাদ গেলে আবার শুরু।",
  "No freezes": "ফ্রিজ নেই",
  "No freezes on your rule. Every week counts.": "আপনার নিয়মে ফ্রিজ নেই। প্রতিটি সপ্তাহ গোনা হয়।",
  "No freezes on your rule: a week without a workout starts it over.": "আপনার নিয়মে ফ্রিজ নেই: ওয়ার্কআউট ছাড়া এক সপ্তাহ, আর স্ট্রিক আবার শুরু।",
  "No workout, and your rule has no freezes, so the streak started over.": "ওয়ার্কআউট হয়নি, আর আপনার নিয়মে ফ্রিজ নেই, তাই স্ট্রিক আবার শুরু হয়েছে।",
  "Weeks already counted stay as they are.": "যে সপ্তাহগুলো গোনা হয়ে গেছে, সেগুলো যেমন আছে তেমনই থাকবে।",
  "You can change it later in Settings. A change counts from then on.": "পরে সেটিংসে বদলাতে পারবেন। বদল তখন থেকে কার্যকর হবে।",
  "Your rule right now: {0}.": "এখন আপনার নিয়ম: {0}।",
  "Your streak counts weeks with at least one workout. Freezes can cover the odd missed week.": "আপনার স্ট্রিক অন্তত একটি ওয়ার্কআউট থাকা সপ্তাহ গোনে। ফ্রিজ মাঝে মাঝে বাদ পড়া সপ্তাহ ঢেকে দিতে পারে।",
  "{0} since the week of {1}.": "{1}-এর সপ্তাহ থেকে {0}।",
  "This phone has no print service. Turn one on in its settings and try again.": "এই ফোনে কোনো প্রিন্ট সার্ভিস নেই। সেটিংসে একটি চালু করে আবার চেষ্টা করো।",
