  "You are letting this trainer see the categories marked here, and change the ones marked suggest or apply. If the trainer works for a gym, its gym lead sees the categories in the gym lead row, never more than view. You can change this or disconnect any time, and it stops working the moment you do. Every look and every change is written to your sharing log, which only you can read.": "আপনি এই ট্রেইনারকে এখানে চিহ্নিত বিভাগগুলো দেখতে দিচ্ছেন, আর পরামর্শ দিন বা সরাসরি বদলান চিহ্নিতগুলো বদলাতেও। ট্রেইনার কোনো জিমে কাজ করলে সেই জিমের প্রধান জিম প্রধান সারির বিভাগগুলো দেখেন, দেখার বেশি কখনও নয়। আপনি যেকোনো সময় এটা বদলাতে বা সংযোগ বিচ্ছিন্ন করতে পারেন, আর করামাত্রই এটা কাজ করা বন্ধ করে দেয়। প্রতিটি দেখা আর প্রতিটি পরিবর্তন আপনার শেয়ারিং লগে লেখা হয়, যেটা শুধু আপনিই পড়তে পারেন।",
