  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "এটা এই সার্ভারের সবার জন্য উন্মুক্ত: এখানে যার অ্যাকাউন্ট আছে সে-ই এটা দেখতে, চেষ্টা করতে আর কপি করতে পারবে। আপনার নাম আর তারিখ সবসময় এর সাথে যাবে। শুধু সেটাই শেয়ার করুন যা আপনার: যা আপনি বানিয়েছেন, রেকর্ড করেছেন বা অন্যকে দেওয়ার অধিকার আপনার আছে। বিল্ট-ইন লাইব্রেরির ব্যায়ামের ছবি আর অ্যানিমেশন লাইসেন্সপ্রাপ্ত এবং কখনোই শেয়ার করা যাবে না। আপনি যেকোনো সময় শেয়ার করা বন্ধ করতে পারেন; অন্যরা আগেই যে কপি নিয়েছে, সেগুলো তাদের কাছেই থাকবে।",
