  "Same brand at another gym? It shares these numbers. Records and Stats still count every gym.": "অন্য জিমে একই ব্র্যান্ড? সেটি এই সংখ্যাগুলো ভাগ করে নেয়। রেকর্ড আর পরিসংখ্যান এখনও সব জিম গোনে।",
