  "Body fat, lean mass, bone mass, body water and BMR, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "বডি ফ্যাট, লিন মাস, হাড়ের ভর, শরীরের পানি আর BMR, যেমন আপনার স্কেল সেভ করেছে। বডি মাপে দেখাবে, আপনার নিজের লেখা মানের সাথে কখনো মিশবে না।",
