  "No map search in openGym Offline. Stand in your gym, tap Current location, done.": "openGym Offline-এ ম্যাপ সার্চ নেই। জিমে দাঁড়িয়ে বর্তমান অবস্থান চাপুন, হয়ে গেল।",
  "Not a single byte left this phone. Your training is nobody’s business but yours.": "এই ফোন থেকে একটা বাইটও বের হয়নি। আপনার ট্রেনিং শুধু আপনারই ব্যাপার।",
  "Nothing yet. Your server hears from this phone when there is something to sync.": "এখনও কিছু নেই। সিঙ্ক করার কিছু থাকলে আপনার সার্ভার এই ফোনের খবর পায়।",
