  "openGym Offline never checks for updates, it can’t. New versions come from wherever you got this one.": "openGym Offline কখনও আপডেট খোঁজে না, পারেই না। নতুন সংস্করণ সেখানেই পাবেন যেখান থেকে এটা পেয়েছেন।",
