  "Finish the workout now? Otherwise it ends by itself at {0}.": "এখনই ওয়ার্কআউট শেষ করবেন? না হলে {0}-এ নিজে শেষ হবে।",
  "Nothing logged for a while. If you’re done, it ends by itself at {0}, saved at your last set.": "অনেকক্ষণ কিছু লেখা হয়নি। শেষ হলে {0}-এ নিজে শেষ হবে, শেষ সেটে সেভ।",
  "Forgotten workouts": "ভুলে যাওয়া ওয়ার্কআউট",
  "If nobody answers, it finishes by itself and never throws anything away. The end is your last set plus its rest, so the time stays honest. Reopen it from History for a day. Your watch asks too.": "কেউ উত্তর না দিলে এটি নিজে শেষ হয় আর কখনও কিছু ফেলে দেয় না। শেষ মানে আপনার শেষ সেট আর তার বিশ্রাম, যাতে সময় সৎ থাকে। ইতিহাস থেকে এক দিন পর্যন্ত আবার খুলতে পারবেন। আপনার ঘড়িও জিজ্ঞেস করে।",
  "Never asks and never ends one by itself.": "কখনও জিজ্ঞেস করে না, নিজে থেকে কিছু শেষও করে না।",
  "The default. Long enough for a chat at the water fountain.": "ডিফল্ট। ওয়াটার কুলারের পাশে গল্পের জন্য যথেষ্ট।",
  "Asks the moment your phone walks out of your gym, then wraps up.": "ফোন জিম থেকে বেরোনোমাত্র জিজ্ঞেস করে, তারপর বন্ধ করে।",
  "Needs the gym reminder: {0}.": "জিম রিমাইন্ডার লাগবে: {0}।",
