  "Minimal": "ন্যূনতম",
  "Needs iOS 17 or later. No animations on the Lock Screen, so the exercise picture is a still. Buttons work without unlocking, Finish opens the app.": "iOS 17 বা নতুন লাগবে। লক স্ক্রিনে অ্যানিমেশন নেই, তাই ব্যায়ামের ছবি স্থির। বোতামগুলো আনলক ছাড়াই চলে, শেষ করুন অ্যাপ খোলে।",
  "No buttons. A tap on it opens openGym.": "কোনো বোতাম নেই। ট্যাপ করলে openGym খোলে।",
  "No room on the Lock Screen. Apple keeps Live Activities to about 160 points tall.": "লক স্ক্রিনে আর জায়গা নেই। Apple লাইভ অ্যাক্টিভিটি প্রায় 160 পয়েন্ট উঁচু রাখে।",
  "No tiles yet.": "এখনো কোনো টাইল নেই।",
  "Nothing here yet, so the workout screen stays as it is. Add a tile or pick a preset.": "এখানে এখনো কিছু নেই, তাই ওয়ার্কআউট স্ক্রিন যেমন আছে তেমনই থাকবে। একটি টাইল যোগ করো বা প্রিসেট বেছে নাও।",
  "Opens openGym, since saving asks what to keep.": "openGym খোলে, কারণ সেভ করার সময় কী রাখবে তা জিজ্ঞেস করে।",
  "Six tiles fit in a notification before it starts mumbling.": "একটি নোটিফিকেশনে ছয়টি টাইল ধরে, তারপর সে বিড়বিড় শুরু করে।",
  "Size of {0}": "{0}-এর আকার",
  "The Dynamic Island holds four tiles. It is an island, not a continent.": "Dynamic Island-এ চারটি টাইল ধরে। এটা একটা দ্বীপ, মহাদেশ নয়।",
  "The pill": "পিল",
