  "The pill shows two tiles beside the camera. Long-press it for the rest.": "পিল ক্যামেরার পাশে দুটি টাইল দেখায়। বাকিগুলোর জন্য লম্বা চাপো।",
  "The widget fits three lines under the set.": "উইজেটে সেটের নিচে তিনটি লাইন ধরে।",
