  "Tiles": "টাইল",
  "Tiles become lines of text, so Android 16 can keep it a Live Update by the clock. While a rest runs, the notification shows its rest buttons.": "টাইলগুলো লেখার লাইন হয়ে যায়, যাতে Android 16 এটাকে ঘড়ির পাশে Live Update হিসেবে রাখতে পারে। বিশ্রামের সময় নোটিফিকেশন তার বিশ্রামের বোতাম দেখায়।",
  "Up to three lines under the set. The widget keeps its own − and + buttons.": "সেটের নিচে তিনটি লাইন পর্যন্ত। উইজেট তার নিজের − আর + বোতাম রাখে।",
