  "Add it as a custom connector in Claude or ChatGPT and sign in with openGym when it asks. Other assistants take a token from below.": "Claude বা ChatGPT-তে কাস্টম কানেক্টর হিসেবে যোগ করুন, আর জিজ্ঞেস করলে openGym দিয়ে সাইন ইন করুন। অন্য সহকারীরা নিচের একটি টোকেন নেয়।",
  "Add “{0}” to my plan": "“{0}” আমার প্ল্যানে যোগ করুন",
