  "Added to your exercises": "আপনার ব্যায়ামে যোগ হয়েছে",
  "After you say yes, it goes back to {0}. Only say yes if you just started this there.": "হ্যাঁ বললে এটি {0}-এ ফিরে যাবে। শুধু তখনই হ্যাঁ বলুন যদি আপনি এইমাত্র সেখান থেকে শুরু করে থাকেন।",
  "Back to openGym": "openGym-এ ফিরে যান",
  "Choose what it may read, and whether it may search the web": "কী পড়তে পারবে আর ওয়েবে খুঁজতে পারবে কিনা, বেছে নিন",
  "Claude, with an API key": "Claude, API কী দিয়ে",
  "Code from OpenRouter": "OpenRouter থেকে কোড",
  "Daily check-ins, sleep, resting heart rate, HRV and steps from your phone, and blood pressure. Off until you switch it on.": "দৈনিক চেক-ইন, ঘুম, বিশ্রামের হৃদস্পন্দন, HRV আর ফোনের স্টেপ, আর রক্তচাপ। আপনি চালু না করা পর্যন্ত বন্ধ।",
  "Estimated one-rep maxes of your main lifts over the last twelve weeks.": "গত বারো সপ্তাহে আপনার প্রধান লিফটগুলোর আনুমানিক এক-রেপ ম্যাক্স।",
  "Find it for me": "আমার জন্য খুঁজে দিন",
  "For questions that need facts from outside your training, like a study or a product.": "যেসব প্রশ্নে আপনার ট্রেনিংয়ের বাইরের তথ্য লাগে, যেমন কোনো গবেষণা বা পণ্য।",
  "From the routines library": "রুটিন লাইব্রেরি থেকে",
  "GPT, with an API key": "GPT, API কী দিয়ে",
  "Gemini, with a free tier to start": "Gemini, শুরু করার জন্য ফ্রি টায়ার সহ",
  "Get a key from {0}": "{0} থেকে একটি কী নিন",
  "Health and how you feel": "স্বাস্থ্য আর আপনি কেমন বোধ করছেন",
  "How it’s done": "কীভাবে করবেন",
  "It shows up under Settings → API tokens, where you can revoke it any time.": "এটি সেটিংস → API টোকেনে দেখা যাবে, সেখানে যেকোনো সময় বাতিল করতে পারবেন।",
  "Looks for Ollama, LM Studio and llama.cpp on the machine running your openGym server and on this phone.": "আপনার openGym সার্ভার চলা মেশিনে আর এই ফোনে Ollama, LM Studio ও llama.cpp খোঁজে।",
  "Nothing answered. Type its address below, like http://192.168.1.20:11434.": "কেউ সাড়া দেয়নি। নিচে ঠিকানা লিখুন, যেমন http://192.168.1.20:11434।",
  "Ollama or LM Studio at home, nothing leaves your Wi-Fi": "বাসায় Ollama বা LM Studio, কিছুই আপনার Wi-Fi ছাড়ে না",
  "On my network": "আমার নেটওয়ার্কে",
  "One sign-in for Claude, GPT, Gemini and more": "Claude, GPT, Gemini আর আরও অনেকের জন্য একটাই সাইন-ইন",
  "OpenRouter makes a key just for this phone, billed to your OpenRouter credits. You can revoke it there any time.": "OpenRouter শুধু এই ফোনের জন্য একটি কী বানায়, খরচ আপনার OpenRouter ক্রেডিট থেকে। সেখানে যেকোনো সময় বাতিল করা যায়।",
  "Or paste a key": "অথবা একটি কী পেস্ট করুন",
  "Paste a code instead": "বদলে একটি কোড পেস্ট করুন",
