  "The OpenRouter sign-in did not work: {0}": "OpenRouter সাইন-ইন কাজ করেনি: {0}",
  "The connection to the AI provider dropped while the Coach was thinking. Try again, ideally on Wi-Fi.": "কোচ ভাবার সময় AI প্রদানকারীর সাথে সংযোগ কেটে গেছে। আবার চেষ্টা করুন, পারলে Wi-Fi-তে।",
  "The connection to your AI provider dropped while the Coach was thinking. Try again, ideally on Wi-Fi.": "কোচ ভাবার সময় আপনার AI প্রদানকারীর সাথে সংযোগ কেটে গেছে। আবার চেষ্টা করুন, পারলে Wi-Fi-তে।",
