  "Your AI provider has no web search.": "আপনার AI প্রদানকারীর ওয়েব সার্চ নেই।",
  "Your latest measurements and the ones from about eight weeks before.": "আপনার সর্বশেষ মাপ আর প্রায় আট সপ্তাহ আগের মাপ।",
  "Your provider may charge a little per search. The pages it read are linked under its answer.": "আপনার প্রদানকারী প্রতি সার্চে সামান্য চার্জ নিতে পারে। যে পাতাগুলো পড়েছে, উত্তরের নিচে লিংক থাকবে।",
  "Your server’s admin hasn’t switched this on.": "আপনার সার্ভারের অ্যাডমিন এটি চালু করেননি।",
