  "MP3, M4A, WAV, AAC or OGG. Yours, or a friend’s with their OK.": "MP3, M4A, WAV, AAC বা OGG। আপনার নিজের গলা, বা অনুমতি নিয়ে কোনো বন্ধুর।",
  "No colours on yours? Name them by level instead, like “Level 3”, and keep the grey.": "আপনার ব্যান্ডের রং নেই? লেভেল দিয়ে নাম দিন, যেমন “লেভেল ৩”, আর ধূসরই রাখুন।",
  "No room for {0} on this size. Try Story, or switch something else off.": "এই মাপে {0}-এর জায়গা নেই। Story চেষ্টা করুন, বা অন্য কিছু বন্ধ করুন।",
