  "Tap a moment to record your own voice for it or pick an audio file, up to {0} seconds.": "একটি মুহূর্তে ট্যাপ করে নিজের গলা রেকর্ড করুন বা অডিও ফাইল বেছে নিন, {0} সেকেন্ড পর্যন্ত।",
